def algorithm(func, dim, lb, ub, budget, rng):
    x = np.random.uniform(lb, ub, size=dim)
    learning_rate = 0.01
    for _ in range(budget):
        g = func(x)
        for i in range(dim-1):
            if 100*(x[i+1]-x[i]**2)**2 > 0:
                x[i] += rng.random() * np.sign(200*(x[i+1]-x[i]**2)*(x[i+1]-x[i]**2) - 2*(1-x[i]))
        if 1-x[dim-1]**2 > 0:
            x[dim-1] += rng.random() * np.sign(-2*(1-x[dim-1])) / (2*100)
        x = np.clip(x, lb, ub)
    return x
